	if (!proto_def->overlay) {
		hdr += hlen;
		len -= hlen;
	}

	return __xdp2_parser_big_ipv6_ppp_node_xdp2_parse(
		parser, hdr, len, metadata, frame, frame_num, ctrl, flags);
